package com.personal.assistant.module.backup.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.module.backup.entity.BackupRecord;import com.personal.assistant.module.backup.service.BackupService;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/operations/backups")public class BackupController{private final BackupService service;public BackupController(BackupService s){service=s;}@GetMapping public ApiResponse<List<BackupRecord>> list(){return ApiResponse.success(service.list());}@PostMapping public ApiResponse<BackupRecord> run(){return ApiResponse.success(service.runFullBackup());}}